<?php
namespace App\Domain\AI\Knowledge\Data;use App\Domain\AI\Knowledge\Enums\KnowledgeSourceType;use App\Domain\AI\Support\StructuredDataGuard;
final readonly class KnowledgeContentData{
 public function __construct(public KnowledgeSourceType$type,public array$content){}
 public static function fromArray(array$data):self{$allowed=['type','body','entries'];$unknown=array_diff(array_keys($data),$allowed);if($unknown)throw new \InvalidArgumentException('Unexpected knowledge fields are not allowed.');$type=KnowledgeSourceType::tryFrom((string)($data['type']??''))??throw new \InvalidArgumentException('Invalid knowledge type.');if($type===KnowledgeSourceType::ManualText){if(array_key_exists('entries',$data))throw new \InvalidArgumentException('Unexpected knowledge fields are not allowed.');$body=self::text($data['body']??null,1,20000);$content=['schema_version'=>'1.0','kind'=>'manual_text','body'=>$body];}else{if(array_key_exists('body',$data))throw new \InvalidArgumentException('Unexpected knowledge fields are not allowed.');$entries=$data['entries']??null;if(!is_array($entries)||!array_is_list($entries)||count($entries)<1||count($entries)>50)throw new \InvalidArgumentException('FAQ entries are invalid.');$clean=[];foreach($entries as$entry){if(!is_array($entry)||array_diff(array_keys($entry),['question','answer']))throw new \InvalidArgumentException('FAQ entry fields are invalid.');$clean[]=['question'=>self::text($entry['question']??null,1,500),'answer'=>self::text($entry['answer']??null,1,4000)];}$content=['schema_version'=>'1.0','kind'=>'faq','entries'=>$clean];}StructuredDataGuard::validate($content);return new self($type,$content);}
 public static function fromPersisted(array$content):self{if(($content['schema_version']??null)!=='1.0')throw new \InvalidArgumentException('Knowledge schema is invalid.');$kind=$content['kind']??null;if($kind==='manual_text'&&array_diff(array_keys($content),['schema_version','kind','body'])===[])return self::fromArray(['type'=>$kind,'body'=>$content['body']??null]);if($kind==='faq'&&array_diff(array_keys($content),['schema_version','kind','entries'])===[])return self::fromArray(['type'=>$kind,'entries'=>$content['entries']??null]);throw new \InvalidArgumentException('Knowledge structure is invalid.');}
 private static function text(mixed$value,int$min,int$max):string{if(!is_string($value))throw new \InvalidArgumentException('Knowledge text is required.');$value=trim($value);if(mb_strlen($value)<$min||mb_strlen($value)>$max||preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u',$value)||preg_match('/<[^>]+>/u',$value))throw new \InvalidArgumentException('Knowledge text is invalid.');return$value;}
}
